 const db=getDB();const go=(v:string)=>{const next=v.startsWith(P)?v:P+v;window.history.pushState({},'',next);setPath(next);setModal(null);setAlert('');setMobile(false);setDetailTab('Tổng quan')};useEffect(()=>{const fn=()=>{setPath(localPath());setModal(null)};window.addEventListener('popstate',fn);return()=>window.removeEventListener('popstate',fn)},[]);
 useEffect(()=>{if(!path.startsWith(P+'/customers')||path===P+'/customers/new')return;let active=true;setLoading(true);crmApi.call<Page<Customer>>('/api/cm/customers',{persona,query:{search,...filters,page,pageSize,sort,order}}).then(result=>{if(active)setList(result)}).catch(e=>{if(active)setAlert(message(e))}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[path,persona,version,search,filters,page,pageSize,sort,order]);
