 const open=(type:string,id?:string,customerId?:string,defaults:Form={})=>{setModal({type,id,customerId});setForm(defaults);setFile(null);setAlert('')};const fset=(k:string,v:any)=>setForm(prev=>({...prev,[k]:v}));const ask=(s:string)=>window.confirm(s);
 const customerId=path.match(/^\/demo\/crm\/customers\/([^/]+)(?:\/edit)?$/)?.[1];const detail=customerId&&customerId!=='new'?db.customers.find(c=>c.customer_id===customerId&&(!c.is_hidden||can(persona,'customer.hide'))):undefined;const allowed=detail&&can(persona,'customer.read')&&(persona==='admin'||(persona==='manager'&&!['000005','000009'].includes(detail.customer_code))||(persona==='accounting'&&!['000004','000009'].includes(detail.customer_code))||db.assignments.some(a=>a.customer_id===detail.customer_id&&a.sale_account_id===persona&&!a.ended_at));const visible=db.customers.filter(c=>!c.is_hidden&&(persona==='admin'||(persona==='manager'&&!['000005','000009'].includes(c.customer_code))||(persona==='accounting'&&!['000004','000009'].includes(c.customer_code))||db.assignments.some(a=>a.customer_id===c.customer_id&&a.sale_account_id===persona&&!a.ended_at)));const activePath=path.replace(P,'');const isDetail=Boolean(customerId&&customerId!=='new'&&!path.endsWith('/edit'));const isEdit=path.endsWith('/edit');
 const managementTitles:Record<string,string>={'/handovers':'Quản trị bàn giao khách hàng','/legal-approvals':'Phê duyệt pháp lý','/groups':'Nhóm khách hàng','/documents/expiring':'Tài liệu đến hạn','/demo-access':'Quyền IAM mô phỏng','/activities':'Công việc'};const title=isDetail?`KHÁCH HÀNG ${allowed?detail?.customer_code:'KHÔNG CÓ QUYỀN'}`:isEdit?'CẬP NHẬT HỒ SƠ':activePath==='/customers/new'?'TẠO KHÁCH HÀNG':(managementTitles[activePath]||Object.entries(managementTitles).find(([k])=>activePath.startsWith(k+'/'))?.[1]||(navs.find(([p])=>p===activePath)||navs.find(([p])=>p&&activePath.startsWith(p))||navs[0])[1]).toLocaleUpperCase('vi');
